import{_ as o}from"./chunks/02-connection-life.XxBuu9d9.js";import{_ as t,o as a,c,a2 as r}from"./chunks/framework.BauHmMU1.js";const u=JSON.parse('{"title":"第二幕 · 一条连接的诞生","description":"","frontmatter":{},"headers":[],"relativePath":"comics/02-connection-life.md","filePath":"comics/02-connection-life.md","lastUpdated":1792595797000}'),d={name:"comics/02-connection-life.md"};function n(i,e,l,s,h,p){return a(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="第二幕-·-一条连接的诞生" tabindex="-1">第二幕 · 一条连接的诞生 <a class="header-anchor" href="#第二幕-·-一条连接的诞生" aria-label="Permalink to &quot;第二幕 · 一条连接的诞生&quot;">​</a></h1><p><img src="'+o+'" alt="WebSocket 生命周期、握手与帧结构"></p><blockquote><p>对应主线教程：<a href="./../02-lifecycle-and-frames">第 2 章 基本概念与工作原理</a></p></blockquote><h2 id="四阶段生命周期" tabindex="-1">四阶段生命周期 <a class="header-anchor" href="#四阶段生命周期" aria-label="Permalink to &quot;四阶段生命周期&quot;">​</a></h2><ol><li><strong>握手请求</strong>：客户端发 HTTP GET，带 <code>Connection: Upgrade</code> + <code>Upgrade: websocket</code></li><li><strong>协议升级</strong>：服务端回 <code>101 Switching Protocols</code>，此后同一条 TCP 不再说 HTTP</li><li><strong>双向通信</strong>：双方互发文本帧 / 二进制帧 / Ping / Pong</li><li><strong>礼貌关闭</strong>：互回 Close 帧（可带状态码与原因），再断 TCP</li></ol><h2 id="握手报文-curl-抓包实测" tabindex="-1">握手报文（curl 抓包实测） <a class="header-anchor" href="#握手报文-curl-抓包实测" aria-label="Permalink to &quot;握手报文（curl 抓包实测）&quot;">​</a></h2><p>请求关键字段：</p><table tabindex="0"><thead><tr><th>头部</th><th>作用</th></tr></thead><tbody><tr><td><code>Sec-WebSocket-Key</code></td><td>16 字节随机数 Base64，握手校验用</td></tr><tr><td><code>Sec-WebSocket-Version: 13</code></td><td>RFC 6455 唯一版本</td></tr><tr><td><code>Origin</code></td><td>来源标识，服务端可据此防 CSWSH</td></tr></tbody></table><p>响应的 <code>Sec-WebSocket-Accept = Base64(SHA1(Key + 固定 GUID))</code>，RFC 经典示例 Key <code>dGhlIHNhbXBsZSBub25jZQ==</code> 必产生 <code>s3pPLMBiTxaQ9kYGzzhZRbK+xOo=</code>。</p><blockquote><p>它只证明&quot;对方真的懂 WebSocket&quot;，<strong>不是身份认证、不是加密</strong>（RFC 6455 §10.8）。</p></blockquote><h2 id="数据帧要点" tabindex="-1">数据帧要点 <a class="header-anchor" href="#数据帧要点" aria-label="Permalink to &quot;数据帧要点&quot;">​</a></h2><ul><li><strong>opcode</strong>：0x1 文本（必须合法 UTF-8）/ 0x2 二进制 / 0x8 Close / 0x9 Ping / 0xA Pong</li><li><strong>MASK 位</strong>：客户端→服务端的帧必须掩码，防恶意字节流欺骗中间代理；密钥明文在帧头，<strong>掩码不等于加密</strong></li><li>Ping 必须回 Pong 并原样带回载荷——所有库（ws、websockets、浏览器）自动处理</li></ul><h2 id="关闭状态码" tabindex="-1">关闭状态码 <a class="header-anchor" href="#关闭状态码" aria-label="Permalink to &quot;关闭状态码&quot;">​</a></h2><p><code>1000</code> 正常 / <code>1001</code> 离开 / <code>1006</code> 异常断开（仅本地哨兵值，<strong>永不上线</strong>）/ <code>1008</code> 策略拒绝 / <code>1011</code> 服务端错误。完整表见主线附录 A。</p><hr><p>上一幕：<a href="./01-why-websocket">第一幕</a> ｜ 下一幕：<a href="./03-http-shoulders">第三幕 · 站在 HTTP 的肩膀上</a></p>',16)])])}const _=t(d,[["render",n]]);export{u as __pageData,_ as default};
